struct MCNRPrevOutput {
	/* For the first frame, there is no previous outputs. valid = false
	 * indicates that contents are empty. */
	bool valid = false;

	/* Generated by the previous frame's MCNR processing with the
	 * corresponding names with the prefix "prev". */
	SharedMailBox<InfoFrame> prevFwMeFst;
	SharedMailBox<InfoFrame> prevFwMmFst;
	SharedMailBox<InfoFrame> prevMeAFst;
	SharedMailBox<InfoFrame> prevMeBFst;
	SharedMailBox<InfoFrame> prevPrevMeAFst;
	SharedMailBox<InfoFrame> prevPrevMeBFst;
	SharedMailBox<InfoFrame> prevMeAMv1;
	SharedMailBox<InfoFrame> prevMeBMv0;
	SharedMailBox<InfoFrame> prevMeL0;
	SharedMailBox<InfoFrame> prevMeL1;
	SharedMailBox<InfoFrame> preDipTnrso;
	SharedMailBox<InfoFrame> prevImg4oF0;
	SharedMailBox<InfoFrame> prevImg4oF1;
	std::vector<SharedMailBox<InfoFrame>> prevDipTnrwo;
};

struct TuningFrames {
	/* Inputs generated by IPA */
	SharedMailBox<InfoFrame> trMeTun; // Tuning of ME for stage HW_LTR_ME_L1
	SharedMailBox<InfoFrame> meATun; // Tuning of ME for stage HW_ME_3PASS_MODE_0
	SharedMailBox<InfoFrame> meBTun; // Tuning of ME for stage HW_ME_3PASS_MODE_1
	SharedMailBox<InfoFrame> meMil; // Tuning of ME for stage HW_ME_3PASS_MODE_1
	SharedMailBox<InfoFrame> ltrTunF1; // Tuning of TR for stage HW_LTR_F1
	SharedMailBox<InfoFrame> ltrTunF4; // Tuning of TR for stage HW_LTR_F4
	SharedMailBox<InfoFrame> trTunF1; // Tuning of TR for stage HW_TR_F1
	SharedMailBox<InfoFrame> trTunF4; // Tuning of TR for stage HW_TR_F4
	SharedMailBox<InfoFrame> ltrTunVbi; // Tuning of LTR for stage HW_LTR_VBI
	SharedMailBox<InfoFrame> wpeTun; // Tuning of WPE for stage HW_WPE_W_F*
	std::vector<SharedMailBox<InfoFrame>> dipTun; // Tuning of DIP for each stages
};

