struct MCNRFrames {
	MeFrames meFrames;
	TrFrames trFrames;
	Dip1Frames dip1Frames;
	Dip2Frames dip2Frames;

	FrameBuffer *videoOut1 = nullptr;
	FrameBuffer *videoOut2 = nullptr;
};

class McnrTasksManager
{
public:
	McnrTasksManager(
		ImgSysDevice *imgSys, DmaHeap *dmaHeap, OnDeviceTuner *odt);

	int configure(const Size yuvInputSize, const Size videoOut1Size,
		      const Size videoOut2Size);

	int start();
	int stop();

	int releaseBuffers();

	void makeMCNRFrames(MCNRFrames &mcnr,
			    MCNRPrevOutput &prev,
			    SharedMailBox<InfoFrame> &meL0,
			    SharedMailBox<InfoFrame> &p1F0,
			    SharedMailBox<InfoFrame> &p1F1,
			    FrameBuffer *videoOut1,
			    FrameBuffer *videoOut2);

	std::tuple<MeATask *, MeBTask *, TrTask *, Dip1Task *, Dip2Task *>
	makeMcnrTasks(MCNRFrames &mcnr, Scheduler *scheduler,
		      const std::string &id, Request *request,
		      uint32_t internalRequestId, ImgSysDevice *imgSys);

private:
	friend class Dip1Task;
	friend class Dip2Task;
	friend class TrTask;
	friend class MeATask;
	friend class MeBTask;
	friend MtkISP7CameraData;

	int configureBuffers();

	bool needCropTNC16x9_;

	Size yuvInputSize_;
	Size videoOut1Size_;
	Size videoOut2Size_;

	std::vector<Size> wtSizes;
	std::vector<Size> mcnrSizes;
	std::vector<Size> meMmapSizes;

	/* MCNR intermediate buffers' pools */
	InfoFramePool fwmeFst_;
	InfoFramePool fwmmFst;
	InfoFramePool fwmmRst_;
	InfoFramePool fwmmMil_;
	InfoFramePool fwmmGyro_;
	InfoFramePool meIn_;
	InfoFramePool meMv0_;
	InfoFramePool meMv1_;
	InfoFramePool meFst_;
	InfoFramePool meLmi_;
	InfoFramePool meFmb0_;
	InfoFramePool meFmb1_;
	InfoFramePool meMmap0_;
	InfoFramePool meMmap1_;
	InfoFramePool meMmap2_;
	InfoFramePool meMmap3_;
	InfoFramePool meConf0_;
	InfoFramePool meConf4_;
	InfoFramePool meConf5_;
	InfoFramePool trawStt_;
	InfoFramePool idi_;
	InfoFramePool tnrSo_;
	InfoFramePool img4oF0_;
	InfoFramePool img4oF1_;
	std::array<InfoFramePool, 7> wt_;
	std::array<InfoFramePool, 7> img3o_;
	std::array<InfoFramePool, 7> tnrmo_;
	std::array<InfoFramePool, 7> vbi_;

	/* Weak ptr for above pools for easier control */
	std::vector<InfoFramePool *> allBufferPools_;
	std::vector<InfoFramePool *> poolsWritenByCpu_;

	ImgSysDevice *imgSys_;
	DmaHeap *dmaHeap_;
	OnDeviceTuner *onDeviceTuner_;
};

class MeATask : public Task
{
public:
	MeATask(Scheduler *scheduler, const std::string &id,
		Request *request, uint32_t internalRequestId,
		ImgSysDevice *imgSys, MCNRFrames &mcnr, McnrTasksManager *manager);

	void run() override;
	void notifyDone() override;

private:
	void allocateOutputBuffers();

	MeFrames frames_;

	uint32_t syncLtrMeA_;

	ImgSysRequestHelper requestHelper_;
	Request *request_;
	[[maybe_unused]] uint32_t internalRequestId_;
	McnrTasksManager *manager_;
	ImgSysDevice *imgSys_;
};

